import { faker } from "@faker-js/faker";
import { writeFileSync } from "node:fs";
import { resolve } from "node:path";

/* This file is the engine which create 5000 assets and pushes them into an sql file to be seeded. */
const ASSET_COUNT = 5000;

function sqlString(value: string) {
  return `'${value.replaceAll("'", "''")}'`;
}

faker.seed(123);

const values = Array.from({ length: ASSET_COUNT }, () => {
  return `(${sqlString(faker.vehicle.bicycle())}, ${faker.string.uuid()})`;
});

const sql = `-- Generated by supabase/seed/generate-assets-seed.ts
-- Do not edit by hand. Re-run: pnpm --filter @repo/db seed:assets:generate

insert into public.assets (name)
values
  ${values.join(",\n  ")};
`;

const outputPath = resolve(process.cwd(), "supabase/assets-seed.sql");

writeFileSync(outputPath, sql, "utf8");
console.log(`Wrote ${ASSET_COUNT} assets to ${outputPath}`);
